L({ id: "c1-participe", lvl: "C1", tr: "ecrit", cat: "syntaxe", t: "Participes et infinitifs passés", en: "Après avoir, une fois terminé, la proposition participiale",
  rule: { h: "Compact structures with participles and past infinitives make formal writing tighter.",
    pts: ["<b>Après + infinitif passé</b>, same subject: <i>après avoir lu le rapport, elle a appelé le directeur; après être arrivés, nous avons dîné</i>.", "<b>Avant de</b> + infinitive; <b>sans</b> + infinitif passé: <i>il est parti sans avoir payé</i>.", "<b>Proposition participiale</b> (its own subject): <i>le dîner terminé, les invités sont partis; la pluie ayant cessé, nous sommes sortis</i>.", "<b>Une fois</b> + participle: <i>une fois le contrat signé, le travail commencera</i>.", "Agreement: <i>après s'être levée, elle…</i> (pronominal: agreement with the subject)."],
    ex: [["Après avoir fini mes études, je suis venue en France.", "After finishing my studies, I came to France."], ["La réunion terminée, chacun est rentré chez soi.", "The meeting over, everyone went home."], ["Une fois les invitations envoyées, nous pourrons souffler.", "Once the invitations are sent, we can breathe."], ["Le train ayant du retard, la conférence a commencé sans elle.", "The train being late, the talk started without her."]],
    warn: "<i>Après</i> is never followed by the present infinitive in this use: <i>après <b>avoir</b> mangé</i>, not <i>après manger</i> (common in speech, but avoid in writing).",
    vn: "<b>Sau khi</b> + động từ → <i>après avoir / être</i> + participe (cùng chủ ngữ). Cấu trúc <i>Le dîner terminé…</i> ≈ <b>Bữa tối xong…</b> — gọn và trang trọng." },
  cards: [["après avoir + p.p.", "after having done", "Après avoir dîné, ils sont sortis.", "After dinner, they went out."], ["après être + p.p.", "after having (être verbs)", "Après être rentrée, elle a dormi.", "After getting home, she slept."], ["sans avoir + p.p.", "without having", "Il est parti sans avoir dit au revoir.", "He left without saying goodbye."], ["une fois + p.p.", "once (done)", "Une fois le dossier complet, envoyez-le.", "Once the file is complete, send it."], ["la décision prise", "the decision (once) taken", "La décision prise, il faut s'y tenir.", "Once the decision is taken, we must stick to it."], ["cela dit", "that said", "Cela dit, je comprends ton point de vue.", "That said, I understand your point of view."], ["ceci étant", "this being so", "Ceci étant, rien n'est perdu.", "This being so, nothing is lost."], ["tout bien considéré", "all things considered", "Tout bien considéré, j'accepte.", "All things considered, I accept."]],
  sent: [["Après avoir étudié la question, le comité a rendu son avis.", "Having studied the question, the committee gave its opinion."], ["Après s'être mariés à Saïgon, ils feront une fête à Paris.", "After marrying in Saigon, they'll have a party in Paris."], ["Elle a signé le contrat sans l'avoir lu en entier.", "She signed the contract without reading it all."], ["Le budget validé, l'équipe a lancé le projet.", "With the budget approved, the team launched the project."], ["Une fois les valises faites, nous avons appelé un taxi.", "Once the cases were packed, we called a taxi."], ["La grève ayant été annulée, les trains circulent normalement.", "The strike having been called off, trains are running normally."], ["Cela dit, il faut reconnaître ses efforts.", "That said, his efforts must be acknowledged."], ["Avant de prendre une décision, consultons l'équipe.", "Before deciding, let's consult the team."], ["Après être restée dix ans à l'étranger, elle est rentrée chez elle.", "After ten years abroad, she went home."], ["Tout bien considéré, cette option est la plus raisonnable.", "All things considered, this option is the most sensible."]],
  nat: [["Après avoir mangé, nous sommes sortis.", "Après manger, nous sommes sortis.", "In writing: après + past infinitive."], ["Après être arrivée, elle a appelé.", "Après avoir arrivée, elle a appelé.", "Arriver → être."], ["Le dîner terminé, nous avons dansé.", "Le dîner terminant, nous avons dansé.", "Completed action → past participle."], ["Il est parti sans avoir payé.", "Il est parti sans payé.", "Sans + infinitive (past)."]],
  mcq: [["Après ___ le film, nous en avons discuté.", "avoir vu", ["voir", "avoir voir", "vu"], "Après + infinitif passé."], ["Après ___, elle a pris un café.", "s'être levée", ["se lever", "s'avoir levée", "levée s'être"], "Pronominal: être + agreement."], ["___ le travail terminé, ils sont partis.", "Une fois", ["Après", "Avant", "Pendant"], "Une fois + noun + participle."], ["La neige ___, l'école a fermé.", "ayant bloqué les routes", ["bloquant hier les routes", "en ayant bloquée", "avoir bloqué"], "Participial clause with its own subject."]],
  gap: [["Après ___ fini ses études, elle a voyagé.", "avoir", "", "After finishing her studies, she travelled.", ["être", "a", "ayant"]], ["Après ___ partis, ils ont regretté.", "être", "", "After leaving, they had regrets.", ["avoir", "étant", "sont"]], ["Il est sorti sans avoir ___ la porte.", "fermé", "fermer", "He went out without closing the door.", ["fermer", "fermait", "fermant"]], ["Une ___ le formulaire rempli, envoyez-le.", "fois", "", "Once the form is filled in, send it.", ["foi", "fois-ci", "fin"]], ["Le contrat ___, les travaux peuvent commencer.", "signé", "signer", "With the contract signed, the work can start.", ["signant", "signer", "signait"]], ["___ dit, je comprends ta position.", "Cela", "", "That said, I understand your position.", ["Ça a", "Ce", "Il"]]],
  fix: [["Après manger, nous avons fait une promenade.", "Après manger", "Après avoir mangé", "In writing: après + past infinitive.", ["Après mangé", "Après être mangé"]], ["Après avoir arrivé, il a téléphoné.", "avoir arrivé", "être arrivé", "Arriver takes être.", ["avoir arrivée", "étant arrivé"]], ["Une fois le dossier envoyer, j'étais soulagée.", "envoyer", "envoyé", "Une fois + noun + past participle.", ["envoyant", "envoyais"]]],
  xf: [["Use après + infinitif passé.", "Elle a lu le courrier, puis elle a répondu.", "Après avoir lu le courrier, elle a répondu."], ["Use a participial clause.", "Quand la réunion a été terminée, tout le monde est parti.", "La réunion terminée, tout le monde est parti."]],
  chat: [["Comment s'est passée ta soirée ?", "Après avoir dîné chez Claire, nous sommes allés voir un concert.", ["Après dîner chez Claire…", "Après avoir dîné, Claire nous sommes allés."], "Après + infinitif passé, same subject."], ["Quand commence le chantier ?", "Une fois le permis obtenu, les travaux pourront commencer.", ["Une fois obtenir le permis…", "Une fois le permis obtenant…"], "Une fois + noun + participle."]]
});
